create or replace function public.prevent_profile_handle_change() returns trigger language plpgsql set search_path = '' as $$ begin if new.handle is distinct from old.handle then raise exception 'Display names cannot be changed after signup.'; end if; return new; end; $$; create or replace trigger prevent_profile_handle_change before update of handle on public.profiles for each row execute function public.prevent_profile_handle_change();